    if p=='library gap vs spec': return 'C'
    if 'not-yet-supported' in c: return 'C'
    if p in ('implementation gap','library bug','typesetter'): return 'A'
    if p in ('design limit','deliberate','packaging'): return 'B'
    if st.startswith('RETIRED'): return 'D'
    if p in ('—','-'): return 'D'
    return '?'
