for k in sorted(b): print(k,len(b[k]),b[k])
for k in sec: print(k,len(sec[k]),sec[k])
print('--- rows >=175 by bucket')
for k in sorted(b): print(k,[n for n in b[k] if n>=175])
print('--- primary class counts'); 
from collections import Counter
print(Counter(primary(c) for n,(st,c) in rows.items()))
print('--- OTHER'); 
for n,(st,c) in rows.items():
    if primary(c).startswith('OTHER'): print(n,st,c[:80])
print('--- A rows ≥175 with class'); 
for n,(st,c) in sorted(rows.items()):
    if n>=175 and bucket(n,st,c)=='A': print(n,'|',st[:40],'|',c[:120])
